using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class DecorInspect {public static string Read(){var sc=SceneManager.GetActiveScene();var map=sc.GetRootGameObjects().Single(g=>g.name=="MyeongjiMap");var rr=map.GetComponentsInChildren<MeshRenderer>();var data=new{sc.path,sc.isDirty,children=map.transform.Cast<Transform>().Select(t=>t.name),lights=rr.Where(r=>!r.name.StartsWith("AB01_")).Select(r=>new{r.name,min=r.bounds.min.ToString(),max=r.bounds.max.ToString(),mats=r.sharedMaterials.Select(m=>m.name)}),buildings=rr.Where(r=>r.name.StartsWith("AB01_")).Select(r=>new{r.name,min=new[]{r.bounds.min.x,r.bounds.min.y,r.bounds.min.z},max=new[]{r.bounds.max.x,r.bounds.max.y,r.bounds.max.z}})};File.WriteAllText("Docs/MapLayout/Myeongji/decor_inspect.json",JsonConvert.SerializeObject(data,Formatting.Indented));return JsonConvert.SerializeObject(new{sc.path,sc.isDirty,children=data.children,lights=data.lights});}}
